from pathlib import Path
import base64,zlib,hashlib
r=Path('/root/nlos_stage2/hybrid_fista_20261031/performance_20261031');r.mkdir(exist_ok=True)
files={'run_fast_rgb.py': ['76a441122e7124cdb91d775d314b8268080dc27c2d3f6a92ce6a006d47b79056', '']}
for name,(digest,payload) in files.items():
 assert Path(name).name==name
 data=zlib.decompress(base64.b64decode(payload));assert hashlib.sha256(data).hexdigest()==digest
 p=r/name
 if p.exists():assert hashlib.sha256(p.read_bytes()).hexdigest()==digest,'Different experimental file exists: '+name
 else:p.write_bytes(data)
 print('INSTALLED_EXPERIMENT',name,len(data),digest,flush=True)
